#
# Regenerate every problems file the submitters read.
#
#   ./regen_problems.sh [llr4|llr5|llr6|all]
#
# The lists are generated, not checked in, but they were regenerated by hand and drifted: the llr4
# set still carried the packet APPENDED after the kernel line (no prefix-cache hit) and page names
# the tree stopped shipping. The submitters only test that a file exists, so a stale list grades a
# treatment nobody meant to run.
set -euo pipefail
cd -- "$(dirname -- "${BASH_SOURCE[0]}")"
PYTHON="${PYTHON:-python3}"
gen() { PYTHONHASHSEED=0 "${PYTHON}" ./make_problems.py "$@"; }

# kimi arms are split in half: a 24 h job cannot hold the full LLR set at its decode rate.
half() {
    local src="$1" stem="$2" n
    n=$(($(wc -l <"${src}") / 2))
    head -n "${n}" "${src}" >"${stem}-h1${3}.jsonl"
    tail -n +$((n + 1)) "${src}" >"${stem}-h2${3}.jsonl"
}

regen_llr45() {
    local gen_id="$1"
    for lang in c cpp fortran; do
        gen --track loop_level_reasoning --language "${lang}" >"problems-${gen_id}-${lang}.jsonl"
        gen --track loop_level_reasoning --language "${lang}" --skills >"problems-${gen_id}-${lang}-skills.jsonl"
        if [[ "${lang}" != cpp ]]; then
            half "problems-${gen_id}-${lang}.jsonl" "problems-${gen_id}-${lang}" ""
            half "problems-${gen_id}-${lang}-skills.jsonl" "problems-${gen_id}-${lang}" "-skills"
        fi
    done
}

# llr6 is the focused two-leg experiment: one tag, three samples per kernel.
regen_llr6() {
    for lang in c fortran; do
        gen --track loop_level_reasoning --language "${lang}" --tag llr-focus40 --repeat 3 \
            >"problems-llr6-${lang}.jsonl"
        gen --track loop_level_reasoning --language "${lang}" --tag llr-focus40 --repeat 3 --skills \
            >"problems-llr6-${lang}-skills.jsonl"
    done
}

case "${1:-all}" in
    llr4) regen_llr45 llr4 ;;
    llr5) regen_llr45 llr5 ;;
    llr6) regen_llr6 ;;
    all) regen_llr45 llr4; regen_llr45 llr5; regen_llr6 ;;
    *) echo "usage: $0 [llr4|llr5|llr6|all]" >&2; exit 2 ;;
esac
